import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const mode = args[0]
let workers = 0
if (args.length === 1 && (mode === 'waves' || mode === 'explain')) {
  // ok
} else if (args.length === 2 && mode === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else if (args.length === 1 && mode === 'pack') {
  fail('error: usage: cli.js waves|explain|pack <workers>')
} else {
  fail('error: usage: cli.js waves|explain|pack <workers>')
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const depLines = []
const NAME = /^[A-Za-z0-9_.-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}

const deps = new Map()
for (const k of cost.keys()) deps.set(k, new Set())
for (const [a, ...ds] of depLines) {
  for (const x of [a, ...ds]) if (!cost.has(x)) fail(`error: unknown task ${x}`)
}
for (const [a, ...ds] of depLines) for (const d of ds) deps.get(a).add(d)

const names = [...cost.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
const sdeps = new Map(names.map((k) => [k, [...deps.get(k)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of sdeps.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v))
        cyc.push(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

// topological order (deps first)
const order = []
{
  const seen = new Set()
  const visit = (u) => {
    seen.add(u)
    for (const v of sdeps.get(u)) if (!seen.has(v)) visit(v)
    order.push(u)
  }
  for (const k of names) if (!seen.has(k)) visit(k)
}
const start = new Map(), finish = new Map(), depth = new Map()
for (const u of order) {
  let s = 0n, d = 0
  for (const v of sdeps.get(u)) {
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
}
let total = 0n
for (const f of finish.values()) if (f > total) total = f

const out = []
if (mode === 'waves') {
  const byDepth = []
  for (const k of names) (byDepth[depth.get(k)] ||= []).push(k)
  byDepth.forEach((g, i) => out.push(`wave ${i}: ${g.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const k of names) out.push(`${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}`)
  out.push(`total ${total}`)
} else {
  const rdeps = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of sdeps.get(k)) rdeps.get(d).push(k)
  const prio = new Map()
  for (const u of [...order].reverse()) {
    let m = 0n
    for (const r of rdeps.get(u)) if (prio.get(r) > m) m = prio.get(r)
    prio.set(u, m + cost.get(u))
  }
  const fin = new Map()
  const freeAt = Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const remaining = new Set(names)
  let t = 0n
  let makespan = 0n
  while (remaining.size) {
    for (;;) {
      let w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let best = null
      for (const k of names) {
        if (!remaining.has(k)) continue
        if (!sdeps.get(k).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best)) best = k
      }
      if (best === null) break
      const f = t + cost.get(best)
      remaining.delete(best)
      fin.set(best, f)
      freeAt[w] = f
      ran[w].push(` ${best}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  ran.forEach((r, i) => out.push(`worker ${i}:${r.join('')}`))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + '\n')
EOF
