{"command":"cat > src/uri.js <<'EOF'
export class UriError extends Error {}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  let scheme = null, authority = null, query = null, fragment = null
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const end = s.slice(2).search(/[/?#]/)
    if (end < 0) { authority = s.slice(2); s = '' } else { authority = s.slice(2, 2 + end); s = s.slice(2 + end) }
  }
  const h = s.indexOf('#')
  if (h >= 0) { fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { query = s.slice(q + 1); s = s.slice(0, q) }
  return { scheme, authority, path: s, query, fragment }
}

function splitAuthority(a) {
  let userinfo = null
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const rb = a.lastIndexOf(']')
  const c = a.indexOf(':', rb + 1)
  let host = a, port = null
  if (c >= 0) { host = a.slice(0, c); port = a.slice(c + 1) }
  return { userinfo, host, port }
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/

function pct(s, name) {
  if (s === null) return null
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new UriError(name)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(ch) ? ch : '%' + h.toUpperCase()
  })
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function removeDots(path) {
  let input = path
  const out = []
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out.pop()
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out.push(seg)
      input = input.slice(seg.length)
    }
  }
  return out.join('')
}

export function normalize(u) {
  const scheme = u.scheme === null ? null : lower(u.scheme)
  let path = pct(u.path, 'path')
  let authority = null
  if (u.authority !== null) {
    const p = splitAuthority(u.authority)
    const userinfo = pct(p.userinfo, 'userinfo')
    const host = lower(pct(p.host, 'host'))
    let port = p.port
    if (port === '' || (scheme !== null && port === DEFAULT_PORTS[scheme])) port = null
    authority = (userinfo !== null ? userinfo + '@' : '') + host + (port !== null ? ':' + port : '')
  }
  const query = pct(u.query, 'query')
  const fragment = pct(u.fragment, 'fragment')
  path = removeDots(path)
  if (authority !== null && path === '') path = '/'
  return serialize({ scheme, authority, path, query, fragment })
}

export function serialize(u) {
  let r = ''
  if (u.scheme !== null) r += u.scheme + ':'
  if (u.authority !== null) r += '//' + u.authority
  r += u.path
  if (u.query !== null) r += '?' + u.query
  if (u.fragment !== null) r += '#' + u.fragment
  return r
}

export function resolve(base, ref) {
  const t = { scheme: null, authority: null, path: '', query: null, fragment: ref.fragment }
  if (ref.scheme !== null) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== null) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== null ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== null && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  return t
}
EOF
cat > src/cli.js <<'EOF'
#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */
import { readFileSync } from 'node:fs'
import { parse, normalize, resolve, UriError } from './uri.js'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) fail('usage: cli.js normalize|resolve')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const out = []
lines.forEach((line, idx) => {
  const n = idx + 1
  try {
    if (mode === 'normalize') {
      out.push(normalize(parse(line)))
    } else {
      const sp = line.indexOf(' ')
      if (sp < 0) fail(`line ${n}: expected a base and a reference`)
      const base = parse(line.slice(0, sp))
      if (base.scheme === null) fail(`line ${n}: the base has no scheme`)
      const t = resolve(base, parse(line.slice(sp + 1)))
      out.push(normalize(t))
    }
  } catch (e) {
    if (e instanceof UriError) fail(`line ${n}: the ${e.message} has a truncated percent-encoding`)
    throw e
  }
})
