export class UriError extends Error {}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  let scheme = null, authority = null, query = null, fragment = null
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const end = s.slice(2).search(/[/?#]/)
    if (end < 0) { authority = s.slice(2); s = '' } else { authority = s.slice(2, 2 + end); s = s.slice(2 + end) }
  }
  const h = s.indexOf('#')
  if (h >= 0) { fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { query = s.slice(q + 1); s = s.slice(0, q) }
  return { scheme, authority, path: s, query, fragment }
}

function splitAuthority(a) {
  let userinfo = null
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const rb = a.lastIndexOf(']')
  const c = a.indexOf(':', rb + 1)
  let host = a, port = null
  if (c >= 0) { host = a.slice(0, c); port = a.slice(c + 1) }
  return { userinfo, host, port }
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/

function pct(s, name) {
  if (s === null) return null
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new UriError(name)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(ch) ? ch : '%' + h.toUpperCase()
  })
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function removeDots(path) {
  let input = path
  const out = []
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out.pop()
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out.push(seg)
      input = input.slice(seg.length)
    }
  }
  return out.join('')
}

