  const n = idx + 1
  try {
    if (mode === 'normalize') {
      out.push(normalize(parse(line)))
    } else {
      const sp = line.indexOf(' ')
      if (sp < 0) fail(`line ${n}: expected a base and a reference`)
      const base = parse(line.slice(0, sp))
      if (base.scheme === null) fail(`line ${n}: the base has no scheme`)
      const t = resolve(base, parse(line.slice(sp + 1)))
      out.push(normalize(t))
    }
  } catch (e) {
    if (e instanceof UriError) fail(`line ${n}: the ${e.message} has a truncated percent-encoding`)
    throw e
  }
})
