export function parse(text) {
  const raw = text.split('\n')
  if (raw[raw.length - 1] === '') raw.pop()
  let names = null
  let sawBallot = false
  const ballots = []
  raw.forEach((rawLine, i) => {
    const n = i + 1
    const line = rawLine.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (names !== null || sawBallot) throw fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) throw fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) throw fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      names = t.slice(1)
    } else if (t[0] === 'ballot') {
      sawBallot = true
      if (t.length < 3) throw fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) throw fail(`error: line ${n}: count must be a positive integer`)
      const known = new Set(names || [])
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!known.has(name)) throw fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      throw fail(`error: line ${n}: unknown directive ${t[0]}`)
    }
  })
  if (names === null) throw fail('error: no candidates')
  return { names, ballots }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count(election) {
  const { names, ballots } = election
  const continuing = new Set(names)
  const history = new Map(names.map((c) => [c, []]))
  const lines = []
  let winner = null
  let k = 0
  for (;;) {
    k++
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) {
        votes.set(c, votes.get(c) + b.count)
        active += b.count
      }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const [c, v] of votes) history.get(c).push(v)
    const order = [...votes.keys()].sort((a, b) => cmp(votes.get(b), votes.get(a)) || cmp(a, b))
    let line = `round ${k}: ` + order.map((c) => `${c}=${votes.get(c)}`).join(' ') + ` exhausted=${total - active}`
    lines.push(line)
    if (active === 0n) break
    const top = order.find((c) => votes.get(c) * 2n > active)
    if (top !== undefined) {
      winner = top
      break
    }
    let min = null
    for (const v of votes.values()) if (min === null || v < min) min = v
    let cand = [...votes.keys()].filter((c) => votes.get(c) === min)
    while (cand.length > 1) {
      let r = 0
      let split = false
      for (; r < k; r++) {
        const vs = cand.map((c) => history.get(c)[r])
        let lo = vs[0]
        let same = true
        for (const v of vs) {
          if (v !== vs[0]) same = false
          if (v < lo) lo = v
        }
        if (!same) {
          cand = cand.filter((c) => history.get(c)[r] === lo)
          split = true
          break
        }
      }
      if (!split) break
    }
    cand.sort(cmp)
    const out = cand[cand.length - 1]
    continuing.delete(out)
    lines.push(`eliminated ${out}`)
  }
  election.roundCount = k
  return { lines, winner }
}
