cat > src/output.js <<'EOF'
const cmp = (a, b) => {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function scalar(n) {
  if (n.t === 'integer') return n.v.toString()
  return JSON.stringify(n.v)
}

function ser(n, ind) {
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    const pad = '  '.repeat(ind + 1)
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${ser(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + '  '.repeat(ind) + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    const pad = '  '.repeat(ind + 1)
    return '[\n' + n.items.map((i) => pad + ser(i, ind + 1)).join(',\n') + '\n' + '  '.repeat(ind) + ']'
  }
  return scalar(n)
}

export const toJson = (root) => ser(root, 0) + '\n'

export function toKeys(root) {
  const out = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n)) {
        const p = path === null ? k : path + '.' + k
        const c = n.map.get(k)
        out.push(`${p} ${c.t}`)
        walk(c, p)
      }
    } else if (n.t === 'array') {
      n.items.forEach((c, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${c.t}`)
        walk(c, p)
      })
    }
  }
  walk(root, null)
  return out.length ? out.join('\n') + '\n' : ''
}
