const fail = (msg) => { throw Object.assign(new Error(msg), { confLine: -1 }) }
const newTable = () => ({ t: 'table', map: new Map(), headered: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => /^[A-Za-z0-9_-]$/.test(c)

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (this.i < this.s.length && isWs(this.s[this.i])) this.i++ }
  peek() { return this.s[this.i] }
  // end of line or start of a comment
  atEnd() { this.ws(); const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }

  string() {
    const q = this.s[this.i++]
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const c = this.s[this.i++]
      if (c === q) return out
      if (q === '"' && c === '\\') {
        if (this.i >= this.s.length) fail('unterminated string')
        const e = this.s[this.i++]
        const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(m, e)) out += m[e]
        else if (e === 'u') {
          const h = this.s.slice(this.i, this.i + 4)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 4
        } else fail('invalid escape \\' + String.fromCodePoint(e.codePointAt(0)))
        if (e !== 'u') continue
      } else out += c
    }
  }

  name() {
    const c = this.peek()
    if (c === '"' || c === "'") return this.string()
    const st = this.i
    while (this.i < this.s.length && isBare(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.peek() === '.') {
        this.i++
