export class UriError extends Error {}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuthority(a) {
  if (a === undefined) return {}
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const from = rest.lastIndexOf(']') + 1
  const c = rest.indexOf(':', from)
  let host = rest, port
  if (c >= 0) { host = rest.slice(0, c); port = rest.slice(c + 1) }
  return { userinfo, host, port }
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

function pct(s) {
  return s.replace(/%([0-9a-fA-F]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

function check(name, s) {
  if (s !== undefined && /%(?![0-9a-fA-F]{2})/.test(s)) {
    throw new UriError(`the ${name} has a truncated percent-encoding`)
  }
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp !== '') {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

function finish(u) {
  const { userinfo, host, port } = splitAuthority(u.authority)
  check('path', u.path)
  check('userinfo', userinfo)
  check('host', host)
  check('query', u.query)
  check('fragment', u.fragment)
  const scheme = u.scheme === undefined ? undefined : lower(u.scheme)
  let r = ''
  if (scheme !== undefined) r += scheme + ':'
  let path = removeDots(pct(u.path))
  if (u.authority !== undefined) {
    let a = ''
    if (userinfo !== undefined) a += pct(userinfo) + '@'
    a += lower(pct(host))
    if (port !== undefined && port !== '' && !(scheme in DEFAULT_PORT && DEFAULT_PORT[scheme] === port)) {
      a += ':' + pct(port)
    }
    r += '//' + a
    if (path === '') path = '/'
  }
  r += path
  if (u.query !== undefined) r += '?' + pct(u.query)
  if (u.fragment !== undefined) r += '#' + pct(u.fragment)
  return r
}

export function normalize(s) {
  return finish(parse(s))
}

export function resolve(baseStr, refStr) {
  const base = parse(baseStr)
  if (base.scheme === undefined) throw new UriError('the base has no scheme')
  const ref = parse(refStr)
  let t
  if (ref.scheme !== undefined) t = { ...ref }
  else if (ref.authority !== undefined) t = { ...ref, scheme: base.scheme }
  else if (ref.path === '') {
