const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

function fail(msg) {
  const e = new Error(msg)
  e.election = true
  throw e
}

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const word = t[0]
    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (word === 'ballot') {
      if (candidates === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!COUNT.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${word}`)
    }
  }
  if (candidates === null) fail('error: no candidates')
  return { candidates, ballots }
}

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const lines = []
  let round = 0
  for (;;) {
    round++
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const pick = b.prefs.find((p) => continuing.has(p))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const listed = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : 1))
    lines.push(`round ${round}: ${listed.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`)
    if (active === 0n) return { lines, rounds: round, winner: null }
    const top = listed[0]
    if (top[1] * 2n > active) return { lines, rounds: round, winner: top[0] }
    const elim = pickElimination(votes, history, round)
    continuing.delete(elim)
    lines.push(`eliminated ${elim}`)
  }
}

function pickElimination(votes, history, rounds) {
  let min = null
  for (const v of votes.values()) if (min === null || v < min) min = v
  let tied = [...votes].filter(([, v]) => v === min).map(([c]) => c)
  restart: for (;;) {
    if (tied.length === 1) return tied[0]
    for (let r = 0; r < rounds; r++) {
      let m = null
      let equal = true
      for (const c of tied) {
        const v = history.get(c)[r]
        if (m !== null && v !== m) equal = false
        if (m === null || v < m) m = v
      }
      if (!equal) {
        tied = tied.filter((c) => history.get(c)[r] === m)
        continue restart
      }
    }
    return tied.reduce((a, b) => (a > b ? a : b))
  }
}
