const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

function uint(field, text, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
  return BigInt(text)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let last = null
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const w = line.split(/\s+/)
    try {
      const d = w[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (d === 'bucket' && w.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        if (d === 'window' && w.length !== 4) fail('expected window <name> <limit> <span>')
        if (d === 'route' && w.length < 3) fail('expected route <prefix> <policy>...')
        if (events.length) fail('declarations must come before the first event')
        if (d === 'route') {
          if (!NAME.test(w[1])) fail(`invalid route prefix ${w[1]}`)
          if (routes.has(w[1])) fail(`prefix ${w[1]} is routed twice`)
          for (const p of w.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
          routes.set(w[1], w.slice(2))
        } else {
          if (!NAME.test(w[1])) fail(`invalid policy name ${w[1]}`)
          let p
          if (d === 'bucket') {
