import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.')

class ScanError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  // consume a digit run with single underscores between digits
  const run = (isD) => {
    if (!isD(s[i])) return
    adv()
    while (i < n) {
      if (isD(s[i])) adv()
      else if (s[i] === '_' && isD(s[i + 1])) { adv(); adv() }
      else break
    }
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const sl = line, sc = col
      adv(); adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { adv(); adv(); depth++ }
        else if (s[i] === '*' && s[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      continue
    }
    const sl = line, sc = col, start = i
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === 'r' && s[i + 1] === '"') {
      adv(); adv()
      const b = i
      while (i < n && s[i] !== '"') adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      const val = s.slice(b, i).join('')
      adv()
      push('rawstring', JSON.stringify(val))
      continue
    }
    if (isIdStart(c)) {
      while (i < n && isIdPart(s[i])) adv()
      const w = s.slice(start, i).join('')
      push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      continue
    }
    if (isDigit(c)) {
      let ok = true
      const p = s[i + 1]
      const pre = c === '0' ? { x: isHex, b: isBin, o: isOct }[(p || '').toLowerCase()] : undefined
      if (pre) {
        adv(); adv()
        if (!pre(s[i])) ok = false
        else run(pre)
      } else {
        run(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) { adv(); run(isDigit) }
        if (s[i] === 'e' || s[i] === 'E') {
          if (isDigit(s[i + 1])) { adv(); run(isDigit) }
          else if ((s[i + 1] === '+' || s[i + 1] === '-') && isDigit(s[i + 2])) { adv(); adv(); run(isDigit) }
        }
      }
      if (isIdPart(s[i])) ok = false
      if (!ok) {
        while (i < n && isIdPart(s[i])) adv()
        throw new ScanError(sl, sc, `invalid number ${s.slice(start, i).join('')}`)
      }
      push('number', s.slice(start, i).join(''))
      continue
    }
    if (c === '"') {
      adv()
      let val = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = s[i]
        if (d === '"') { adv(); break }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') { val += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = s[i]
        const bad = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { adv(); val += simple[e] }
        else if (e === 'x') {
          if (!(isHex(s[i + 1]) && isHex(s[i + 2]))) throw bad()
          adv()
          val += String.fromCodePoint(parseInt(adv() + adv(), 16))
        } else if (e === 'u') {
          if (s[i + 1] !== '{') throw bad()
          let j = i + 2, h = ''
          while (isHex(s[j])) h += s[j++]
          if (!h || s[j] !== '}') throw bad()
          const v = parseInt(h, 16)
          if (v > 0x10ffff) throw bad()
          while (i <= j) adv()
          val += String.fromCodePoint(v)
        } else throw bad()
      }
      push('string', JSON.stringify(val))
      continue
    }
    const two = c + (s[i + 1] ?? '')
    if (PUNCT2.has(two)) { adv(); adv(); push('punct', two); continue }
    if (PUNCT1.has(c)) { adv(); push('punct', c); continue }
    throw new ScanError(line, col, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let tokens
try {
  tokens = scan(readFileSync(0, 'utf8'))
} catch (err) {
  if (!(err instanceof ScanError)) throw err
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
EOF
