        if (d !== '\\') { val += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = s[i]
        const bad = () => new ScanError(bl, bc, `invalid escape \\${e}`)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) { adv(); val += simple[e] }
        else if (e === 'x') {
          if (!(isHex(s[i + 1]) && isHex(s[i + 2]))) throw bad()
          adv()
          val += String.fromCodePoint(parseInt(adv() + adv(), 16))
        } else if (e === 'u') {
          if (s[i + 1] !== '{') throw bad()
          let j = i + 2, h = ''
          while (isHex(s[j])) h += s[j++]
          if (!h || s[j] !== '}') throw bad()
          const v = parseInt(h, 16)
          if (v > 0x10ffff) throw bad()
          while (i <= j) adv()
          val += String.fromCodePoint(v)
        } else throw bad()
      }
      push('string', JSON.stringify(val))
      continue
    }
    const two = c + (s[i + 1] ?? '')
    if (PUNCT2.has(two)) { adv(); adv(); push('punct', two); continue }
    if (PUNCT1.has(c)) { adv(); push('punct', c); continue }
    throw new ScanError(line, col, `unexpected character ${c}`)
  }
  return tokens
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let tokens
try {
  tokens = scan(readFileSync(0, 'utf8'))
} catch (err) {
  if (!(err instanceof ScanError)) throw err
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
