{"file_path":"src/render.js","content":"/** Output renderers for the parsed document tree. */

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

function sortedKeys(table) {
  return [...table.map.keys()].sort(cmp)
}

function scalarJson(node) {
  switch (node.t) {
    case 'integer': return node.v.toString()
    case 'float': return JSON.stringify(node.v)
    default: return JSON.stringify(node.v)
  }
}

function emit(node, indent) {
  if (node.t === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const pad = '  '.repeat(indent + 1)
    const parts = keys.map((k) => `${pad}${JSON.stringify(k)}: ${emit(node.map.get(k), indent + 1)}`)
    return `{\n${parts.join(',\n')}\n${'  '.repeat(indent)}}`
  }
  if (node.t === 'array') {
    if (node.items.length === 0) return '[]'
    const pad = '  '.repeat(indent + 1)
    const parts = node.items.map((n) => `${pad}${emit(n, indent + 1)}`)
    return `[\n${parts.join(',\n')}\n${'  '.repeat(indent)}]`
  }
  return scalarJson(node)
}

export function renderJson(root) {
  return emit(root, 0) + '\n'
}

export function renderKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : `${path}.${k}`
        lines.push(`${p} ${node.map.get(k).t}`)
        walk(node.map.get(k), p)
      }
    } else if (node.t === 'array') {
      node.items.forEach((item, i) => {
        const p = `${path}[${i}]`
        lines.push(`${p} ${item.t}`)
        walk(item, p)
      })
    }
  }
  walk(root, null)
  return lines.length ? lines.join('\n') + '\n' : ''
}
"}

{"file_path":"src/parser.js","content":"/** Parser for the configuration document; builds a tree of typed nodes. */

class ConfError extends Error {}

const fail = (msg) => {
  const e = new ConfError(msg)
  e.confMessage = msg
  throw e
}

const newTable = (explicit = false) => ({ t: 'table', map: new Map(), explicit })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const joinPath = (base, name) => (base === '' ? name : `${base}.${name}`)
const DIGITS = '\\d+(?:_\\d+)*'
const NUM = new RegExp(`^[+-]?${DIGITS}(\\.${DIGITS})?([eE][+-]?${DIGITS})?$`)

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }

  skipWs() {
    const s = this.s
    while (this.i < s.length && isWs(s[this.i])) this.i++
    if (s[this.i] === '#' || s[this.i] === ';') this.i = s.length
  }

  atEnd() {
    return this.i >= this.s.length
  }

  peek() {
    return this.s[this.i]
  }

  basicString() {
    const s = this.s
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= s.length) fail('unterminated string')
      const c = s[this.i]
      if (c === '"') { this.i++; return out }
      if (c !== '\\') { out += c; this.i++; continue }
      this.i++
      if (this.i >= s.length) fail('unterminated string')
      const e = s[this.i]
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(simple, e)) { out += simple[e]; this.i++ } else if (e === 'u') {
        const hex = s.slice(this.i + 1, this.i + 5)
        if (!/^[0-9a-fA-F]{4}$/.test(hex)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(hex, 16))
        this.i += 5
      } else {
        const ch = String.fromCodePoint(s.codePointAt(this.i))
        fail(`invalid escape \\${ch}`)
      }
    }
  }

  literalString() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) fail('unterminated string')
    const v = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return v
  }

  name() {
    const c = this.peek()
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dottedName() {
    const parts = []
    for (;;) {
      this.skipWsOnly()
      parts.push(this.name())
      this.skipWsOnly()
      if (this.peek() === '.') this.i++
      else return parts
    }
  }

  skipWsOnly() {
    while (this.i < this.s.length && isWs(this.s[this.i])) this.i++
  }

  value(path) {
    this.skipWs()
    if (this.atEnd()) fail('expected a value')
    const c = this.peek()
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basicString() }
    if (c === "'") return { t: 'string', v: this.literalString() }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inlineTable(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const word = this.s.slice(st, this.i)
    if (word === 'true') return { t: 'boolean', v: true }
    if (word === 'false') return { t: 'boolean', v: false }
    const m = NUM.exec(word)
    if (!m) fail(`invalid value ${word}`)
    const text = word.replace(/_/g, '')
    if (m[1] === undefined && m[2] === undefined) return { t: 'integer', v: BigInt(text) }
    return { t: 'float', v: Number(text) }
  }

  array(path) {
    this.i++
    const node = { t: 'array', items: [], aot: false }
    this.skipWs()
    if (this.peek() === ']') { this.i++; return node }
    for (;;) {
      node.items.push(this.value(path))
      this.skipWs()
      const c = this.peek()
      if (c === ',') {
        this.i++
        this.skipWs()
        if (this.peek() === ']') { this.i++; return node }
      } else if (c === ']') { this.i++; return node } else fail('unterminated array')
    }
  }

  inlineTable(path) {
    this.i++
    const table = newTable()
    this.skipWs()
    if (this.peek() === '}') { this.i++; return table }
    for (;;) {
      this.skipWs()
      if (this.atEnd()) fail('unterminated inline table')
      const names = this.dottedName()
      if (this.peek() !== '=') fail('expected = in an inline table')
      this.i++
      const val = this.value(joinPath(path, names.join('.')))
      assign(table, path, names, val)
      this.skipWs()
      const c = this.peek()
      if (c === ',') this.i++
      else if (c === '}') { this.i++; return table } else fail('unterminated inline table')
    }
  }
}

/** Descend one step through an existing node as a dotted/header path walk. */
function stepInto(node, path, notMsg) {
  if (node.t === 'table') return node
  if (node.t === 'array' && node.aot) return node.items[node.items.length - 1]
  return fail(`${path} ${notMsg}`)
}

function assign(table, basePath, names, val) {
  let cur = table
  let path = basePath
  for (let k = 0; k < names.length - 1; k++) {
    path = joinPath(path, names[k])
    const ex = cur.map.get(names[k])
    if (ex === undefined) {
      const t = newTable()
      cur.map.set(names[k], t)
      cur = t
    } else cur = stepInto(ex, path, 'is not a table')
  }
  const last = names[names.length - 1]
  path = joinPath(path, last)
  if (cur.map.has(last)) fail(`key ${path} is defined twice`)
  cur.map.set(last, val)
}

function parseHeader(p, root, lineText) {
  const isArr = lineText[p.i + 1] === '['
  p.i += isArr ? 2 : 1
  const names = p.dottedName()
  if (p.peek() !== ']') fail('unterminated table header')
  p.i++
  if (isArr) {
    if (p.peek() !== ']') fail('unterminated table header')
    p.i++
  }
  p.skipWs()
  if (!p.atEnd()) fail('trailing text after a table header')
  let cur = root
  let path = ''
  for (let k = 0; k < names.length - 1; k++) {
    path = joinPath(path, names[k])
    const ex = cur.map.get(names[k])
    if (ex === undefined) {
      const t = newTable()
      cur.map.set(names[k], t)
      cur = t
    } else cur = stepInto(ex, path, 'is not a table')
  }
  const last = names[names.length - 1]
  path = joinPath(path, last)
  const ex = cur.map.get(last)
  if (isArr) {
    const fresh = newTable(true)
    if (ex === undefined) cur.map.set(last, { t: 'array', items: [fresh], aot: true })
    else if (ex.t === 'array' && ex.aot) ex.items.push(fresh)
    else fail(`${path} is not an array of tables`)
    return { table: fresh, path }
  }
  if (ex === undefined) {
    const t = newTable(true)
    cur.map.set(last, t)
    return { table: t, path }
  }
  if (ex.t !== 'table') fail(`${path} is not a table`)
  if (ex.explicit) fail(`table ${path} is defined twice`)
  ex.explicit = true
  return { table: ex, path }
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable(true)
  let current = { table: root, path: '' }
  for (let n = 0; n < lines.length; n++) {
    try {
      const text = lines[n]
      const p = new LineParser(text)
      p.skipWsOnly()
      if (p.atEnd() || p.peek() === '#' || p.peek() === ';') continue
      if (p.peek() === '[') {
        current = parseHeader(p, root, text)
        continue
      }
      const names = p.dottedName()
      if (p.peek() !== '=') fail('expected key = value')
      p.i++
      const val = p.value(joinPath(current.path, names.join('.')))
      p.skipWs()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(current.table, current.path, names, val)
    } catch (e) {
      if (e instanceof ConfError) e.line = n + 1
      throw e
    }
  }
  return root
}
"}

