{"file_path":"src/addr.js","content":"export function colIndex(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function colName(n) {
  let s = ''
  while (n > 0) {
    const r = (n - 1) % 26
    s = String.fromCharCode(65 + r) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

export function makeAddress(col, row) {
  return { col, row, key: colName(col) + row }
}

export function parseAddress(text) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(text)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  return { col: colIndex(letters), row, key: letters + row }
}
"}

{"file_path":"src/parse.js","content":"import { parseAddress, makeAddress } from './addr.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  return toks
}

// Returns { ast, refs, misplaced } or null when the grammar rejects the body.
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let pos = 0
  const refs = []
  let misplaced = false
  const fail = () => { throw new Error('grammar') }
  const isOp = (v, k = 0) => toks[pos + k] && toks[pos + k].t === 'op' && toks[pos + k].v === v

  function addrNode(word) {
    const a = parseAddress(word)
    if (a) refs.push(a)
    return a
  }

  function rangeNode(w1, w2) {
    const a = parseAddress(w1)
    const b = parseAddress(w2)
    if (!a || !b) return { k: 'badref' }
    const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
    const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
    const cells = []
    for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) cells.push(makeAddress(c, r))
    for (const x of cells) refs.push(x)
    return { k: 'range', cells }
  }

  function comparison() {
    let l = additive()
    while (toks[pos] && toks[pos].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[pos].v)) {
      const op = toks[pos++].v
      l = { k: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (isOp('+') || isOp('-')) {
      const op = toks[pos++].v
      l = { k: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[pos++].v
      l = { k: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) {
      pos++
      return { k: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[pos++].v
      return { k: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[pos]
    if (!t) fail()
    if (t.t === 'num') { pos++; return { k: 'num', v: t.v } }
    if (t.t === 'op') {
      if (t.v === '(') {
        pos++
        const e = comparison()
        if (!isOp(')')) fail()
        pos++
        return e
      }
      fail()
    }
    // word
    if (isOp('(', 1)) {
      pos += 2
      const args = []
      if (isOp(')')) pos++
      else {
        for (;;) {
          const a = toks[pos], b = toks[pos + 1], c = toks[pos + 2]
          const nxt = toks[pos + 3]
          if (a && a.t === 'word' && b && b.t === 'op' && b.v === ':' && c && c.t === 'word' &&
              !(nxt && nxt.t === 'op' && nxt.v === '(') &&
              nxt && nxt.t === 'op' && (nxt.v === ',' || nxt.v === ')')) {
            pos += 3
            args.push(rangeNode(a.v, c.v))
          } else args.push(comparison())
          if (isOp(',')) { pos++; continue }
          if (isOp(')')) { pos++; break }
          fail()
        }
      }
      return { k: 'call', name: t.v.toUpperCase(), args }
    }
    pos++
    if (isOp(':') && toks[pos + 1] && toks[pos + 1].t === 'word' && !isOp('(', 2)) {
      const w2 = toks[pos + 1].v
      pos += 2
      misplaced = true
      rangeNode(t.v, w2)
      return { k: 'badref' }
    }
    const up = t.v.toUpperCase()
