{"file_path":"src/eval.js","content":"import { parseFormula } from './parse.js'

const ERRORS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const err = (e) => ({ type: 'err', v: e })
const num = (v) => ({ type: 'num', v })
const bool = (v) => ({ type: 'bool', v })

function finite(n) {
  return Number.isFinite(n) ? num(n) : err('#DIV/0!')
}

function toNum(x) {
  if (x.type === 'num') return x
  if (x.type === 'bool') return num(x.v ? 1 : 0)
  return err('#VALUE!')
}

function cmpStr(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const rank = { num: 0, text: 1, bool: 2 }

function compare(a, b) {
  if (a.type !== b.type) return rank[a.type] - rank[b.type]
  if (a.type === 'text') return cmpStr(a.v, b.v)
  if (a.type === 'bool') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

export class Sheet {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  print(key) {
    const v = this.cellValue(key)
    switch (v.type) {
      case 'num': return String(Number(v.v.toPrecision(10)))
      case 'bool': return v.v ? 'TRUE' : 'FALSE'
      default: return v.v
    }
  }

  cellValue(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    const cell = this.cells.get(key)
    if (!cell) return num(0)
    if (this.busy.has(key)) return err('#CYCLE!')
    this.busy.add(key)
    const v = this.compute(cell.content)
    this.busy.delete(key)
    this.memo.set(key, v)
    return v
  }

  compute(content) {
    if (content[0] === '=') {
      const p = parseFormula(content.slice(1))
      if (!p || p.misplaced) return err('#ERR!')
      return this.ev(p.ast)
    }
    if (content === '') return num(0)
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
    if (ERRORS.has(content)) return err(content)
    return { type: 'text', v: content }
  }

  ev(n) {
    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return bool(n.v)
      case 'badref': return err('#REF!')
      case 'range': return err('#ERR!')
      case 'ref': return this.cellValue(n.key)
      case 'neg': {
        const v = this.ev(n.e)
        if (v.type === 'err') return v
        const x = toNum(v)
        if (x.type === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l)
    const r = this.ev(n.r)
    if (l.type === 'err') return l
    if (r.type === 'err') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      switch (n.op) {
        case '=': return bool(c === 0)
        case '<>': return bool(c !== 0)
        case '<': return bool(c < 0)
        case '<=': return bool(c <= 0)
        case '>': return bool(c > 0)
        default: return bool(c >= 0)
      }
    }
    const a = toNum(l)
    if (a.type === 'err') return a
    const b = toNum(r)
    if (b.type === 'err') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
      case '*': return finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
      default: return finite(Math.pow(a.v, b.v))
    }
  }

  // Values an argument contributes, or a single error.
  argValues(a) {
    if (a.k === 'range') return a.cells.map((c) => this.cellValue(c.key))
    return [this.ev(a)]
  }

  call(n) {
    const name = n.name
    const args = n.args
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      const c = this.single(args[0])
      if (c.type === 'err') return c
      let truth
      if (c.type === 'bool') truth = c.v
      else if (c.type === 'num') truth = c.v !== 0
      else return err('#VALUE!')
      return this.single(truth ? args[1] : args[2])
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      const v = this.single(args[0])
      if (v.type === 'err') return v
      const x = toNum(v)
      return x.type === 'err' ? x : num(Math.abs(x.v))
    }
    if (args.length < 1) return err('#ERR!')
    const vals = []
    for (const a of args) vals.push(...this.argValues(a))
    for (const v of vals) if (v.type === 'err') return v
    if (name === 'COUNT') return num(vals.filter((v) => v.type === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.type === 'err') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      default: return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }

  single(a) {
    const vs = this.argValues(a)
    for (const v of vs) if (v.type === 'err') return v
    return vs.length === 1 ? vs[0] : err('#VALUE!')
  }
}
"}

