{"file_path":"src/addr.js","content":"export function colIndex(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function colName(n) {
  let s = ''
  while (n > 0) {
    const r = (n - 1) % 26
    s = String.fromCharCode(65 + r) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

export function makeAddress(col, row) {
  return { col, row, key: colName(col) + row }
}

export function parseAddress(text) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(text)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  return { col: colIndex(letters), row, key: letters + row }
}
"}

