      l = { k: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[pos++].v
      l = { k: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) {
      pos++
      return { k: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[pos++].v
      return { k: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[pos]
    if (!t) fail()
    if (t.t === 'num') { pos++; return { k: 'num', v: t.v } }
