import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Sheet } from './eval.js'
import { parseAddress } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const stripped = lines[i].replace(/^[ \t]+/, '')
  if (stripped === '' || stripped[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(stripped)
  const raw = m[1]
  const addr = parseAddress(raw)
  if (!addr) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${raw}\n`)
    process.exit(2)
  }
  if (cells.has(addr.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${addr.key} is declared twice\n`)
    process.exit(2)
  }
  cells.set(addr.key, { addr, content: m[2] })
}

const sorted = [...cells.values()].sort(
  (a, b) => a.addr.col - b.addr.col || a.addr.row - b.addr.row
)

const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) out.push(`${c.addr.key}=${sheet.print(c.addr.key)}`)
} else {
  for (const c of sorted) {
    let line = `${c.addr.key}:`
    if (c.content[0] === '=') {
      const p = parseFormula(c.content.slice(1))
      if (p) {
        const set = new Map()
        for (const a of p.refs) set.set(a.key, a)
        const list = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
        for (const a of list) line += ` ${a.key}`
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
"}

