{"file_path":"src/scanner.js","content":"export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && (c === '_' || /^\p{L}$/u.test(c))
const isIdCont = (c) => isLetter(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

export function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const lines = new Array(n + 1)
  const cols = new Array(n + 1)
  let l = 1
  let c = 1
  for (let i = 0; i < n; i++) {
    lines[i] = l
    cols[i] = c
    if (s[i] === '\n') {
      l++
      c = 1
    } else if (s[i] === '\t') c = Math.floor((c - 1) / 4) * 4 + 5
    else c++
  }
  lines[n] = l
  cols[n] = c
  const fail = (i, reason) => {
    throw new ScanError(lines[i], cols[i], reason)
  }

  const tokens = []
  let i = 0
  const push = (start, kind, body) => tokens.push({ line: lines[start], col: cols[start], kind, body })

  while (i < n) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      i++
      continue
    }
    if (ch === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') i++
      continue
    }
    if (ch === '/' && s[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (depth > 0) {
        if (i >= n) fail(start, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') {
          depth++
          i += 2
        } else if (s[i] === '*' && s[i + 1] === '/') {
          depth--
          i += 2
        } else i++
      }
      continue
    }
    if (ch === 'r' && s[i + 1] === '"') {
      const start = i
      i += 2
      let v = ''
      while (i < n && s[i] !== '"') v += s[i++]
      if (i >= n) fail(start, 'unterminated string')
      i++
      push(start, 'rawstring', JSON.stringify(v))
      continue
    }
    if (isLetter(ch)) {
      const start = i
      while (isIdCont(s[i])) i++
      const w = s.slice(start, i).join('')
      push(start, KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      continue
    }
    if (isDigit(ch)) {
      const start = i
      const digits = (test) => {
        i++
        for (;;) {
          if (test(s[i])) i++
          else if (s[i] === '_' && test(s[i - 1]) && test(s[i + 1])) i += 2
          else break
        }
      }
      const p = (s[i + 1] || '').toLowerCase()
      const radix = ch === '0' ? { x: isHex, b: (d) => d === '0' || d === '1', o: (d) => d !== undefined && d >= '0' && d <= '7' }[p] : undefined
      let bad = false
      if (radix) {
        i += 2
        if (radix(s[i])) digits(radix)
        else bad = true
      } else {
        digits(isDigit)
        if (s[i] === '.' && isDigit(s[i + 1])) {
          i++
          digits(isDigit)
        }
        if (s[i] === 'e' || s[i] === 'E') {
          if (isDigit(s[i + 1])) {
            i++
            digits(isDigit)
          } else if ((s[i + 1] === '+' || s[i + 1] === '-') && isDigit(s[i + 2])) {
            i += 2
            digits(isDigit)
          }
        }
      }
      if (bad || isIdCont(s[i])) {
        while (isIdCont(s[i])) i++
        fail(start, `invalid number ${s.slice(start, i).join('')}`)
      }
      push(start, 'number', s.slice(start, i).join(''))
      continue
    }
    if (ch === '"') {
      const start = i
      i++
      let v = ''
      for (;;) {
        if (i >= n) fail(start, 'unterminated string')
        const d = s[i]
        if (d === '"') {
          i++
          break
        }
        if (d === '\n') fail(i, 'newline in string')
        if (d !== '\\') {
          v += d
          i++
          continue
        }
        const bs = i
        const e = s[i + 1]
        if (e === undefined) fail(start, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) {
          v += simple[e]
          i += 2
        } else if (e === 'x') {
          if (!isHex(s[i + 2]) || !isHex(s[i + 3])) fail(bs, 'invalid escape \\x')
          v += String.fromCharCode(parseInt(s[i + 2] + s[i + 3], 16))
          i += 4
        } else if (e === 'u') {
          if (s[i + 2] !== '{') fail(bs, 'invalid escape \\u')
          let j = i + 3
          let h = ''
          while (isHex(s[j])) h += s[j++]
          if (h === '' || s[j] !== '}') fail(bs, 'invalid escape \\u')
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) fail(bs, 'invalid escape \\u')
          v += String.fromCodePoint(cp)
          i = j + 1
        } else fail(bs, `invalid escape \\${e}`)
      }
      push(start, 'string', JSON.stringify(v))
      continue
    }
    const two = ch + (s[i + 1] ?? '')
    if (PUNCT2.has(two)) {
      push(i, 'punct', two)
      i += 2
      continue
    }
    if (PUNCT1.has(ch)) {
      push(i, 'punct', ch)
      i++
      continue
    }
    fail(i, `unexpected character ${ch}`)
  }
  return tokens
}
"}

