{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { parseFormula, collectDeps } from './formula.js'
import { Evaluator, formatValue } from './eval.js'
import { addrString, compareAddr } from './addr.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}
const mode = args[0]
const input = readFileSync(0, 'utf8')

let cells
try {
  cells = parseSheet(input)
} catch (e) {
  if (e instanceof SheetError) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}

const keys = [...cells.values()].sort((a, b) => compareAddr(a, b))
let out = ''
if (mode === 'values') {
  const ev = new Evaluator(cells)
  for (const c of keys) out += `${addrString(c)}=${formatValue(ev.valueOf(c))}\n`
} else {
  for (const c of keys) {
    let line = addrString(c) + ':'
    if (c.content.startsWith('=')) {
      const ast = parseFormula(c.content.slice(1))
      if (ast) for (const a of collectDeps(ast)) line += ' ' + addrString(a)
    }
    out += line + '\n'
  }
}
process.stdout.write(out)
"}

{"file_path":"src/addr.js","content":"export function colName(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  return String.fromCharCode(64 + Math.floor((n - 1) / 26)) + String.fromCharCode(65 + ((n - 1) % 26))
}

export function addrString(a) {
  return colName(a.col) + a.row
}

export function compareAddr(a, b) {
  return a.col - b.col || a.row - b.row
}

// Returns {col,row} or null when the text is not an address in range.
export function parseAddr(text) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(text)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const l = m[1].toUpperCase()
  const col = l.length === 1 ? l.charCodeAt(0) - 64 : (l.charCodeAt(0) - 64) * 26 + l.charCodeAt(1) - 64
  return { col, row }
}

export function keyOf(a) {
  return a.col * 1000 + a.row
}
"}

{"file_path":"src/sheet.js","content":"import { parseAddr, keyOf } from './addr.js'

export class SheetError extends Error {}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const text = m[1]
    const a = parseAddr(text)
    if (!a) throw new SheetError(`error: line ${i + 1}: invalid cell address ${text}`)
    const k = keyOf(a)
    if (cells.has(k)) {
      throw new SheetError(`error: line ${i + 1}: cell ${text} is declared twice`)
    }
    cells.set(k, { col: a.col, row: a.row, content: m[2] })
  })
  return cells
}
"}

{"file_path":"src/formula.js","content":"import { parseAddr, compareAddr } from './addr.js'

class Bad extends Error {}

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=+\-*\/^():,])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] })
      i += m[0].length
    } else throw new Bad()
  }
  return toks
}

// Returns an AST, or null when the grammar rejects the formula (cell is #ERR!).
export function parseFormula(body) {
  try {
    const toks = tokenize(body)
    let p = 0
    const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
    let misplaced = false

    const isRefWord = (tok) => tok && tok.t === 'word' && !/^(TRUE|FALSE)$/i.test(tok.v)
    const rangeAhead = () =>
      isRefWord(toks[p]) && toks[p + 1]?.t === 'op' && toks[p + 1].v === ':' &&
      isRefWord(toks[p + 2]) && !(toks[p + 3]?.t === 'op' && toks[p + 3].v === '(')
    const takeRange = () => {
      const a = toks[p].v
      const b = toks[p + 2].v
      p += 3
      return { k: 'range', a, b }
    }

    function cmp() {
      let l = add()
      while (toks[p] && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
        const op = toks[p++].v
        l = { k: 'bin', op, l, r: add() }
      }
      return l
    }
    function add() {
      let l = mul()
      while (isOp('+') || isOp('-')) {
        const op = toks[p++].v
        l = { k: 'bin', op, l, r: mul() }
      }
      return l
    }
    function mul() {
      let l = pow()
      while (isOp('*') || isOp('/')) {
        const op = toks[p++].v
        l = { k: 'bin', op, l, r: pow() }
      }
      return l
    }
    function pow() {
      const l = unary()
      if (isOp('^')) {
        p++
        return { k: 'bin', op: '^', l, r: pow() }
      }
      return l
    }
    function unary() {
      if (isOp('-') || isOp('+')) {
        const op = toks[p++].v
        return { k: 'un', op, e: unary() }
      }
      return primary()
    }
    function primary() {
      const tok = toks[p]
      if (!tok) throw new Bad()
      if (tok.t === 'num') { p++; return { k: 'num', v: tok.v } }
      if (tok.t === 'op') {
        if (tok.v !== '(') throw new Bad()
        p++
        const e = cmp()
        if (!isOp(')')) throw new Bad()
        p++
        return e
      }
      if (rangeAhead()) {
        misplaced = true
        return takeRange()
      }
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            if (rangeAhead()) {
              const save = p
              const r = takeRange()
              if (isOp(',') || isOp(')')) args.push(r)
              else { p = save; args.push(cmp()) }
            } else args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            throw new Bad()
          }
        }
        return { k: 'call', name: tok.v.toUpperCase(), args }
      }
      const u = tok.v.toUpperCase()
      if (u === 'TRUE') return { k: 'bool', v: true }
      if (u === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', w: tok.v }
    }

    const ast = cmp()
    if (p !== toks.length) throw new Bad()
    if (misplaced) return { k: 'err' , inner: ast }
    return ast
  } catch (e) {
    if (e instanceof Bad) return null
    throw e
  }
}

// Expand a range node to addresses in ascending column then row; null if an end is invalid.
export function expandRange(node) {
  const a = parseAddr(node.a)
  const b = parseAddr(node.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) {
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push({ col: c, row: r })
  }
  return out
}

export function collectDeps(ast) {
  const seen = new Map()
  const add = (a) => seen.set(a.col * 1000 + a.row, a)
  const walk = (n) => {
    switch (n.k) {
      case 'err': walk(n.inner); break
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': walk(n.e); break
      case 'call': n.args.forEach(walk); break
      case 'ref': { const a = parseAddr(n.w); if (a) add(a); break }
      case 'range': { const r = expandRange(n); if (r) r.forEach(add); break }
    }
  }
  walk(ast)
  return [...seen.values()].sort(compareAddr)
}
"}

{"file_path":"src/eval.js","content":"import { parseAddr, keyOf } from './addr.js'
import { parseFormula, expandRange } from './formula.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ t: 'err', v: code })
const num = (v) => (Number.isFinite(v) ? { t: 'num', v } : err('#DIV/0!'))

export function formatValue(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function cpCompare(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const rank = { num: 0, text: 1, bool: 2 }
function compareValues(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'text') return cpCompare(a.v, b.v)
  if (a.t === 'bool') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function toNum(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return { t: 'num', v: v.v ? 1 : 0 }
  if (v.t === 'err') return v
  return err('#VALUE!')
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  valueOf(cell) {
    return this.cellValue(cell.col, cell.row)
  }

  cellValue(col, row) {
    const k = keyOf({ col, row })
    const cell = this.cells.get(k)
    if (!cell) return { t: 'num', v: 0 }
    if (this.memo.has(k)) return this.memo.get(k)
    if (this.busy.has(k)) return err('#CYCLE!')
    this.busy.add(k)
    const v = this.compute(cell.content)
    this.busy.delete(k)
    this.memo.set(k, v)
    return v
  }

  compute(content) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (!ast || ast.k === 'err') return err('#ERR!')
      return this.ev(ast)
    }
    if (content === '') return { t: 'num', v: 0 }
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return { t: 'num', v: Number(content) }
    if (ERRORS.includes(content)) return err(content)
    return { t: 'text', v: content }
  }

  ev(n) {
    switch (n.k) {
      case 'num': return { t: 'num', v: n.v }
      case 'bool': return { t: 'bool', v: n.v }
      case 'ref': {
        const a = parseAddr(n.w)
        return a ? this.cellValue(a.col, a.row) : err('#REF!')
      }
      case 'range': return err('#ERR!')
      case 'un': {
        const x = toNum(this.ev(n.e))
        if (x.t === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l)
    if (l.t === 'err') return l
    const r = this.ev(n.r)
    if (r.t === 'err') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compareValues(l, r)
      const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'bool', v: res }
    }
    const a = toNum(l)
    if (a.t === 'err') return a
    const b = toNum(r)
    if (b.t === 'err') return b
    switch (n.op) {
      case '+': return num(a.v + b.v)
      case '-': return num(a.v - b.v)
      case '*': return num(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : num(a.v / b.v)
      case '^': return num(Math.pow(a.v, b.v))
    }
  }

  // Values of one argument; ranges expand to every covered cell.
  argValues(a) {
    if (a.k === 'range') {
      const cs = expandRange(a)
      if (!cs) return [err('#REF!')]
      return cs.map((c) => this.cellValue(c.col, c.row))
    }
    return [this.ev(a)]
  }

  scalar(a) {
    const vs = this.argValues(a)
    const e = vs.find((v) => v.t === 'err')
    if (e) return e
    return vs.length === 1 ? vs[0] : err('#VALUE!')
  }

  call(n) {
    const name = n.name
    const argc = n.args.length
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if (name === 'IF' ? argc !== 3 : name === 'ABS' ? argc !== 1 : argc < 1) return err('#ERR!')
    if (name === 'IF') {
      const c = this.scalar(n.args[0])
      if (c.t === 'err') return c
      let truth
      if (c.t === 'bool') truth = c.v
      else if (c.t === 'num') truth = c.v !== 0
      else return err('#VALUE!')
      return this.scalar(n.args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      const x = toNum(this.scalar(n.args[0]))
      return x.t === 'err' ? x : num(Math.abs(x.v))
    }
    const vals = n.args.flatMap((a) => this.argValues(a))
    const e = vals.find((v) => v.t === 'err')
    if (e) return e
    if (name === 'COUNT') return { t: 'num', v: vals.filter((v) => v.t === 'num').length }
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'err') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return num(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      case 'AVG': return num(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }
}
"}

