      }
      return l
    }
    function mul() {
      let l = pow()
      while (isOp('*') || isOp('/')) {
        const op = toks[p++].v
        l = { k: 'bin', op, l, r: pow() }
      }
      return l
    }
    function pow() {
      const l = unary()
      if (isOp('^')) {
        p++
        return { k: 'bin', op: '^', l, r: pow() }
      }
      return l
    }
    function unary() {
      if (isOp('-') || isOp('+')) {
        const op = toks[p++].v
        return { k: 'un', op, e: unary() }
      }
      return primary()
    }
    function primary() {
      const tok = toks[p]
      if (!tok) throw new Bad()
      if (tok.t === 'num') { p++; return { k: 'num', v: tok.v } }
      if (tok.t === 'op') {
        if (tok.v !== '(') throw new Bad()
        p++
        const e = cmp()
        if (!isOp(')')) throw new Bad()
        p++
        return e
      }
      if (rangeAhead()) {
        misplaced = true
        return takeRange()
      }
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            if (rangeAhead()) {
              const save = p
              const r = takeRange()
              if (isOp(',') || isOp(')')) args.push(r)
              else { p = save; args.push(cmp()) }
            } else args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            throw new Bad()
          }
        }
        return { k: 'call', name: tok.v.toUpperCase(), args }
      }
      const u = tok.v.toUpperCase()
      if (u === 'TRUE') return { k: 'bool', v: true }
      if (u === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', w: tok.v }
    }

    const ast = cmp()
    if (p !== toks.length) throw new Bad()
    if (misplaced) return { k: 'err' , inner: ast }
    return ast
  } catch (e) {
    if (e instanceof Bad) return null
    throw e
  }
}

// Expand a range node to addresses in ascending column then row; null if an end is invalid.
export function expandRange(node) {
  const a = parseAddr(node.a)
  const b = parseAddr(node.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) {
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push({ col: c, row: r })
  }
  return out
}

export function collectDeps(ast) {
  const seen = new Map()
  const add = (a) => seen.set(a.col * 1000 + a.row, a)
  const walk = (n) => {
    switch (n.k) {
      case 'err': walk(n.inner); break
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': walk(n.e); break
      case 'call': n.args.forEach(walk); break
      case 'ref': { const a = parseAddr(n.w); if (a) add(a); break }
      case 'range': { const r = expandRange(n); if (r) r.forEach(add); break }
    }
  }
  walk(ast)
  return [...seen.values()].sort(compareAddr)
}
"}

{"file_path":"src/eval.js","content":"import { parseAddr, keyOf } from './addr.js'
import { parseFormula, expandRange } from './formula.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (code) => ({ t: 'err', v: code })
const num = (v) => (Number.isFinite(v) ? { t: 'num', v } : err('#DIV/0!'))

export function formatValue(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function cpCompare(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

const rank = { num: 0, text: 1, bool: 2 }
function compareValues(a, b) {
  if (a.t !== b.t) return rank[a.t] - rank[b.t]
  if (a.t === 'text') return cpCompare(a.v, b.v)
  if (a.t === 'bool') return Number(a.v) - Number(b.v)
  return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
}

function toNum(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return { t: 'num', v: v.v ? 1 : 0 }
  if (v.t === 'err') return v
  return err('#VALUE!')
}

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.busy = new Set()
  }

  valueOf(cell) {
    return this.cellValue(cell.col, cell.row)
  }

  cellValue(col, row) {
    const k = keyOf({ col, row })
    const cell = this.cells.get(k)
    if (!cell) return { t: 'num', v: 0 }
    if (this.memo.has(k)) return this.memo.get(k)
    if (this.busy.has(k)) return err('#CYCLE!')
    this.busy.add(k)
    const v = this.compute(cell.content)
    this.busy.delete(k)
    this.memo.set(k, v)
    return v
  }

  compute(content) {
    if (content.startsWith('=')) {
      const ast = parseFormula(content.slice(1))
      if (!ast || ast.k === 'err') return err('#ERR!')
      return this.ev(ast)
    }
    if (content === '') return { t: 'num', v: 0 }
    if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return { t: 'num', v: Number(content) }
    if (ERRORS.includes(content)) return err(content)
    return { t: 'text', v: content }
  }

  ev(n) {
    switch (n.k) {
      case 'num': return { t: 'num', v: n.v }
      case 'bool': return { t: 'bool', v: n.v }
      case 'ref': {
        const a = parseAddr(n.w)
        return a ? this.cellValue(a.col, a.row) : err('#REF!')
      }
      case 'range': return err('#ERR!')
      case 'un': {
        const x = toNum(this.ev(n.e))
        if (x.t === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
    return err('#ERR!')
  }

  bin(n) {
    const l = this.ev(n.l)
    if (l.t === 'err') return l
    const r = this.ev(n.r)
    if (r.t === 'err') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compareValues(l, r)
      const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'bool', v: res }
    }
    const a = toNum(l)
    if (a.t === 'err') return a
    const b = toNum(r)
    if (b.t === 'err') return b
    switch (n.op) {
      case '+': return num(a.v + b.v)
      case '-': return num(a.v - b.v)
      case '*': return num(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : num(a.v / b.v)
      case '^': return num(Math.pow(a.v, b.v))
    }
  }

  // Values of one argument; ranges expand to every covered cell.
  argValues(a) {
    if (a.k === 'range') {
      const cs = expandRange(a)
      if (!cs) return [err('#REF!')]
      return cs.map((c) => this.cellValue(c.col, c.row))
    }
    return [this.ev(a)]
  }

  scalar(a) {
    const vs = this.argValues(a)
    const e = vs.find((v) => v.t === 'err')
    if (e) return e
    return vs.length === 1 ? vs[0] : err('#VALUE!')
  }

  call(n) {
    const name = n.name
    const argc = n.args.length
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    if (name === 'IF' ? argc !== 3 : name === 'ABS' ? argc !== 1 : argc < 1) return err('#ERR!')
    if (name === 'IF') {
      const c = this.scalar(n.args[0])
      if (c.t === 'err') return c
      let truth
      if (c.t === 'bool') truth = c.v
      else if (c.t === 'num') truth = c.v !== 0
      else return err('#VALUE!')
      return this.scalar(n.args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      const x = toNum(this.scalar(n.args[0]))
      return x.t === 'err' ? x : num(Math.abs(x.v))
    }
    const vals = n.args.flatMap((a) => this.argValues(a))
    const e = vals.find((v) => v.t === 'err')
    if (e) return e
    if (name === 'COUNT') return { t: 'num', v: vals.filter((v) => v.t === 'num').length }
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'err') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return num(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      case 'AVG': return num(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }
}
"}

