function diff(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const changes = []
  let i = 0, j = 0, bs = 0, ss = 0
  const close = () => {
    if (i > bs || j > ss) changes.push({ bs, be: i, ss, se: j })
  }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      close(); i++; j++; bs = i; ss = j
    } else if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) i++
    else j++
  }
  close()
  return changes
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0]))
    fail('usage: cli.js merge|merge2|regions')
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) l === '%%%' ? docs.push([]) : docs[docs.length - 1].push(l)
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const all = [
    ...diff(base, mine).map(c => ({ ...c, side: 0 })),
    ...diff(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)

  const out = []
  let conflict = false
  const sides = [mine, theirs]
  let pos = 0, k = 0
  while (k < all.length) {
    if (all[k].bs > pos) {
      const n = all[k].bs - pos
      if (mode === 'regions') out.push(`stable ${n}`)
      else out.push(...base.slice(pos, all[k].bs))
    }
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    pos = re
    const baseL = base.slice(rs, re)
    const rep = sides.map((doc, s) => {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) return baseL
      const minB = Math.min(...cs.map(c => c.bs))
      const minS = Math.min(...cs.map(c => c.ss))
      const maxB = Math.max(...cs.map(c => c.be))
      const maxS = Math.max(...cs.map(c => c.se))
      return doc.slice(minS - (minB - rs), maxS + (re - maxB))
    })
    const [m, t] = rep
    let label, res
    if (same(m, t)) { label = 'both'; res = m }
    else if (same(m, baseL)) { label = 'theirs'; res = t }
    else if (same(t, baseL)) { label = 'mine'; res = m }
    else label = 'conflict'
    if (label === 'conflict') {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseL.length} theirs=${t.length}`)
      else {
        out.push('<<<<<<< mine', ...m)
        if (mode === 'merge') out.push('||||||| base', ...baseL)
        out.push('=======', ...t, '>>>>>>> theirs')
      }
    } else if (mode === 'regions') out.push(`${label} ${res.length}`)
    else out.push(...res)
  }
  if (pos < base.length) {
    if (mode === 'regions') out.push(`stable ${base.length - pos}`)
    else out.push(...base.slice(pos))
  }
  process.stdout.write(out.map(l => l + '\n').join(''))
  process.exitCode = conflict ? 1 : 0
}

