function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ who, bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(); i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mode, mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const out = []
  let conflict = false
  let pos = 0
  const stable = n => {
    if (n > 0) {
      if (mode === 'regions') out.push(`stable ${n}`)
      else out.push(...base.slice(pos, pos + n))
    }
  }
  const sides = [mine, theirs]
  let k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    stable(rs - pos)
    const baseL = base.slice(rs, re)
    const rep = who => {
      const cs = group.filter(c => c.who === who)
      if (!cs.length) return baseL
      const first = cs[0], last = cs[cs.length - 1]
      const minS = Math.min(...cs.map(c => c.bs)), maxE = Math.max(...cs.map(c => c.be))
      return sides[who].slice(first.ss - (minS - rs), last.se + (re - maxE))
    }
    let kind, lines
    if (group.length === 1) {
      kind = group[0].who ? 'theirs' : 'mine'
      lines = rep(group[0].who)
    } else {
      const m = rep(0), t = rep(1)
      if (eq(m, t)) { kind = 'both'; lines = m }
      else if (eq(m, baseL)) { kind = 'theirs'; lines = t }
      else if (eq(t, baseL)) { kind = 'mine'; lines = m }
      else {
        kind = 'conflict'
        conflict = true
        if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseL.length} theirs=${t.length}`)
        else {
          out.push('<<<<<<< mine', ...m)
          if (mode === 'merge') out.push('||||||| base', ...baseL)
          out.push('=======', ...t, '>>>>>>> theirs')
        }
      }
    }
    if (kind !== 'conflict') {
      if (mode === 'regions') out.push(`${kind} ${lines.length}`)
      else out.push(...lines)
    }
    pos = re
  }
  stable(base.length - pos)
  return { out, conflict }
}
